import sys


def isDivisible(num):
    if num % 3 == 0 and num % 5 == 0:
        return 1
    return 0


def main():
    data = sys.stdin.read().split()
    if not data:
        return
    num = int(data[0])
    if isDivisible(num):
        print("Divisible")
    else:
        print("Not Divisible")


if __name__ == "__main__":
    main()
